def split_csv(line):
    fields = []
    i = 0

    while i < len(line):
        if line[i] == '"':
            # Quoted field
            field = ""
            i += 1
            while i < len(line):
                if line[i] == '"':
                    if i + 1 < len(line) and line[i + 1] == '"':
                        # Doubled quote - represents one quote character
                        field += '"'
                        i += 2
                    else:
                        # End of quoted field
                        i += 1
                        # Check what follows: comma or end of line
                        if i < len(line):
                            if line[i] == ',':
                                i += 1
                                fields.append(field)
                                break
                            else:
                                # Invalid: closing quote not followed by comma or end
                                return None
                        else:
                            # End of line
                            fields.append(field)
                            break
                else:
                    field += line[i]
                    i += 1
            else:
                # Reached end of line without closing quote
                return None
        else:
            # Unquoted field
            field = ""
            while i < len(line) and line[i] != ',':
                if line[i] == '"':
                    # Double quote not allowed in unquoted field
                    return None
                field += line[i]
                i += 1

            fields.append(field)

            if i < len(line) and line[i] == ',':
                i += 1

    return fields

